package main

import (
	"strings"
)

const generatedHeader = "{/* Generated by tools/docsgen (make docs-gen). " +
	"Do not edit: changes are overwritten. */}\n\n"

func renderOptions(options []option) []byte {
	var b strings.Builder
	b.WriteString(generatedHeader)
	writeRow(&b, "Option", "Environment Variable", "Config File", "Default", "Description")
	writeRow(&b, "---", "---", "---", "---", "---")
	for i := range options {
		o := &options[i]
		flag := codeSpan("--" + o.name)
		if o.shorthand != "" {
			flag += ", " + codeSpan("-"+o.shorthand)
		}
		writeRow(&b, flag, codeOrDash(o.envVar), codeOrDash(o.jsonKey), o.value, escape(o.usage))
	}

	return []byte(b.String())
}

func renderMetrics(metrics []metric) []byte {
	var b strings.Builder
	b.WriteString(generatedHeader)
	writeRow(&b, "Metric", "Type", "Labels", "Description")
	writeRow(&b, "---", "---", "---", "---")
	for i := range metrics {
		m := &metrics[i]
		labels := make([]string, 0, len(m.labels))
		for _, label := range m.labels {
			labels = append(labels, codeSpan(label))
		}
		labelCell := strings.Join(labels, ", ")
		if labelCell == "" {
			labelCell = "-"
		}
		writeRow(&b, codeSpan(m.name), m.kind, labelCell, escape(m.help))
	}

	return []byte(b.String())
}

func writeRow(b *strings.Builder, cells ...string) {
	b.WriteString("| " + strings.Join(cells, " | ") + " |\n")
}

func codeOrDash(text string) string {
	if text == "" {
		return "-"
	}

	return codeSpan(text)
}

func codeSpan(text string) string {
	text = strings.ReplaceAll(text, "|", `\|`)
	if strings.Contains(text, "`") {
		return "`` " + text + " ``"
	}

	return "`" + text + "`"
}

func escape(text string) string {
	text = strings.Join(strings.Fields(text), " ")
	var b strings.Builder
	for _, r := range text {
		if strings.ContainsRune("\\`*_{}[]<>|~", r) {
			b.WriteByte('\\')
		}
		b.WriteRune(r)
	}

	return b.String()
}
